def transform(grid):
    h,w=len(grid),len(grid[0])
    p=[(r,c) for r in range(h) for c in range(w) if grid[r][c]]
    color=grid[p[0][0]][p[0][1]]
    r0,r1=min(r for r,c in p),max(r for r,c in p)
    c0,c1=min(c for r,c in p),max(c for r,c in p)
    out=[[0]*w for _ in range(h)]
    for r,c in p:
        dr=r-r0; dc=c-c0
        if dr==0:
            nr,nc=r,c-(c1-c0)
        elif dr==r1-r0:
            nr,nc=r,c
        elif dc==0:
            nr,nc=r,c+dr-2
        elif dc==c1-c0:
            nr,nc=r,c+dr-4
        else:
            continue
        if 0<=nc<w: out[nr][nc]=color
    return out
